  const text=input.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('') || input.text || input.content;
  if(typeof text!=='string'||text.length>60000) throw new Error('Missing or oversized AI JSON');
  return JSON.parse(text.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,''));
