  const csv=[['id','title','url','feed','published_at','relevance_score'].map(cell).join(','),...pack.sources.map(s=>[s.id,s.title,s.url,s.feed,s.publishedAt,s.score].map(cell).join(','))].join('\n');
  return {...pack,humanReviewRequired:true,markdown:lines.join('\n')+'\n',sourcesCsv:csv+'\n'};
}

