function cleanText(value, limit = 1800) {
  if (Array.isArray(value)) value = value[0];
  if (value && typeof value === 'object') value = value._ || '';
  return String(value || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/\s+/g, ' ').trim().slice(0, limit);
}
function canonicalUrl(value) {
  const s = String(value || '').trim();
  const m = s.match(/^(https?):\/\/([a-z0-9.-]+)(?::(\d+))?(\/[^?#\s]*)?(?:\?([^#\s]*))?(?:#[^\s]*)?$/i);
  if (!m || !m[2].includes('.') || m[2].endsWith('.local') || /^\d+\.\d+\.\d+\.\d+$/.test(m[2]) || (m[3] && !['80','443'].includes(m[3]))) return null;
  const pairs = (m[5] || '').split('&').filter(Boolean).filter(p => !/^(utm_[^=]*|fbclid|gclid|ref)=/i.test(p)).sort();
  return m[1].toLowerCase() + '://' + m[2].toLowerCase() + (m[3] ? ':'+m[3] : '') + (m[4] || '/') + (pairs.length ? '?'+pairs.join('&') : '');
}
function validateConfig(raw) {
  const c = {...raw};
  if (!['demo','live'].includes(c.mode)) throw new Error('mode must be demo or live');
  if (!['normal','empty','feed-failure','invalid-brief','invalid-content'].includes(c.demoScenario)) throw new Error('Unknown demoScenario');
  if (typeof c.enableAI !== 'boolean') throw new Error('enableAI must be a boolean');
  for (const [key, min, max] of [['lookbackHours',1,720],['maxStories',1,12],['maxPerFeed',1,100]]) {
    if (!Number.isInteger(c[key]) || c[key]<min || c[key]>max) throw new Error('Invalid '+key);
  }
  if (!Array.isArray(c.keywords) || !c.keywords.length || c.keywords.some(x=>typeof x!=='string'||!x.trim()||x.length>80)) throw new Error('Provide keywords');
  c.keywords = c.keywords.map(x=>x.toLowerCase().trim()).slice(0,20);
  if (!Array.isArray(c.feeds) || !c.feeds.length || c.feeds.length>6) throw new Error('Provide 1-6 feeds');
  if (!Array.isArray(c.allowedFeedHosts) || c.allowedFeedHosts.some(x=>typeof x!=='string')) throw new Error('Provide allowedFeedHosts');
  for (const feed of c.feeds) {
    const url = canonicalUrl(feed.url);
    const host = url?.match(/^https:\/\/([^/:]+)\//)?.[1];
    if (!host || !c.allowedFeedHosts.includes(host)) throw new Error('Feed must use HTTPS on an allowed hostname');
    if (typeof feed.name !== 'string' || !feed.name.trim()) throw new Error('Feed name required');
    feed.url=url;
  }
  if (!Array.isArray(c.knownUrls) || c.knownUrls.some(x=>typeof x!=='string')) throw new Error('knownUrls must be an array of URLs');
  c.asOf = new Date().toISOString();
  c.topic = cleanText(c.topic,120) || 'Automation intelligence';
  c.audience = cleanText(c.audience,300) || 'Automation teams';
  return c;
}
function array(value) { return value == null ? [] : Array.isArray(value) ? value : [value]; }
function extractFeed(parsed, context) {
  if (parsed.error) return {feed:context.feed.name,articles:[],failures:[{feed:context.feed.name,reason:'XML parsing failed'}]};
  const root = parsed.xml || parsed.data || parsed;
  const channel = array(root.rss?.channel)[0];
  const atom = root.feed;
  if (!channel && !atom) return {feed:context.feed.name,articles:[],failures:[{feed:context.feed.name,reason:'Unsupported RSS/Atom document'}]};
  const entries = channel ? array(channel.item) : array(atom.entry);
  const articles = entries.slice(0,context.config.maxPerFeed).map(entry => {
    const links=array(entry.link);
    const atomLink=links.find(l=>l && typeof l==='object' && (!l.$?.rel || l.$.rel==='alternate'));
    const url=canonicalUrl(channel ? cleanText(entry.link,1600) : atomLink?.$?.href || cleanText(entry.link,1600));
    return {title:cleanText(entry.title,220),url,publishedAt:cleanText(entry.pubDate || entry.published || entry.updated || entry['dc:date'],100),
      excerpt:cleanText(entry.description || entry.summary || entry['content:encoded'] || entry.content),feed:context.feed.name};
  }).filter(a=>a.title&&a.url);
