}
function rankReports(config, reports) {
  const stats={feeds:reports.length,feedFailures:reports.flatMap(r=>r.failures||[]),received:0,duplicates:0,known:0,stale:0,undated:0,irrelevant:0};
  const unique=new Map(); const known=new Set(config.knownUrls.map(canonicalUrl).filter(Boolean)); const now=Date.parse(config.asOf);
  for (const report of reports) for (const article of report.articles||[]) {
    stats.received++;
    const url=canonicalUrl(article.url);
    if (!url) continue;
    if(unique.has(url)){stats.duplicates++;continue;}
    unique.set(url,{...article,url});
  }
  const ranked=[];
  for(const article of unique.values()) {
    if(known.has(article.url)){stats.known++;continue;}
    const date=Date.parse(article.publishedAt);
    if(!Number.isFinite(date)){stats.undated++;continue;}
    const age=(now-date)/3600000;
    if(age>config.lookbackHours||age<-.25){stats.stale++;continue;}
    const hay=(article.title+' '+article.excerpt).toLowerCase();
    const matched=config.keywords.filter(k=>new RegExp('(^|[^a-z0-9])'+k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?=$|[^a-z0-9])','i').test(hay));
    if(!matched.length){stats.irrelevant++;continue;}
    ranked.push({...article,publishedAt:new Date(date).toISOString(),matchedKeywords:matched,score:matched.length*20+Math.max(0,20-age/config.lookbackHours*20)});
  }
  ranked.sort((a,b)=>b.score-a.score||b.publishedAt.localeCompare(a.publishedAt));
  const sources=ranked.slice(0,config.maxStories).map((a,i)=>({...a,id:'S'+String(i+1).padStart(3,'0')}));
  return {config,sources,stats,hasSources:sources.length>0,seenUrls:[...new Set([...config.knownUrls,...sources.map(s=>s.url)])]};
}
function parseResponse(input) {
  if(input.error) throw new Error('AI provider request failed');
  if(input.headline || input.linkedin) return input;
  const text=input.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('') || input.text || input.content;
  if(typeof text!=='string'||text.length>60000) throw new Error('Missing or oversized AI JSON');
  return JSON.parse(text.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,''));
}
function validateBrief(input,pack) {
  let brief=null;const reasons=[]; const ids=new Set(pack.sources.map(s=>s.id));
  try {
    brief=parseResponse(input);
    if(typeof brief.headline!=='string'||!brief.headline.trim()||brief.headline.length>160) reasons.push('Invalid briefing headline');
    if(!Array.isArray(brief.findings)||!brief.findings.length||brief.findings.length>12) reasons.push('Provide 1-12 findings');
    for(const f of Array.isArray(brief.findings)?brief.findings:[]) {
      if(typeof f.summary!=='string'||!f.summary.trim()||f.summary.length>1800) reasons.push('Invalid finding summary');
      if(!Array.isArray(f.sourceIds)||!f.sourceIds.length||f.sourceIds.some(id=>!ids.has(id))) reasons.push('Finding cites unavailable source');
      if(f.confidence!=='limited') reasons.push('Excerpt-only findings must use limited confidence');
    }
    if(!Array.isArray(brief.uncertainties)||brief.uncertainties.some(x=>typeof x!=='string')) reasons.push('Missing uncertainty notes');
  } catch(e){reasons.push(e.message);}
  return {...pack,brief,briefValid:reasons.length===0,reviewReasons:reasons};
}
function validateContent(input,pack) {
  let content=null;const reasons=[];const ids=new Set(pack.sources.map(s=>s.id));
  try {
    content=parseResponse(input);
    for(const key of ['linkedin','newsletter']) {
      const draft=content[key];
      if(!draft||typeof draft.text!=='string'||!draft.text.trim()||draft.text.length>(key==='linkedin'?2500:7000)) reasons.push('Invalid '+key+' draft');
      if(!Array.isArray(draft?.sourceIds)||!draft.sourceIds.length||draft.sourceIds.some(id=>!ids.has(id))) reasons.push('Unknown '+key+' citation');
      if(/https?:\/\//i.test(draft?.text||'')) reasons.push('Use source IDs rather than model-generated URLs');
    }
  }catch(e){reasons.push(e.message);}
