  const lines=['# '+label(pack.config.topic),'','Status: '+pack.status,'','Human review is required before use or publication.','',pack.config.mode==='demo'?'DEMO: fictional source stories and simulated AI responses.':'Evidence is limited to feed titles/excerpts; full articles were not fetched.',''];
